{
 "quarter": "Q3 FY26",
 "callDate": "2026-01-29",
 "guidance": [
  {
   "metric": "volume",
   "statement": "Target to expand smartphone camera modules from 40 million units to 190 million to 200 million units per annum.",
   "quote": "target to expand volumes of smartphone camera modules from 40 million units in this fiscal to 190 million to 200 million units per annum.",
   "page": 4,
   "horizon": "medium term",
   "quantitative": true
  },
  {
   "metric": "revenue",
   "statement": "IT hardware revenue for next year is expected to be around INR3,500 crores to INR4,000 crores.",
   "quote": "We feel that for next year, the numbers are going to be somewhere around INR3,500 crores to INR4,000 crores.",
   "page": 16,
   "horizon": "next financial year",
   "quantitative": true
  },
  {
   "metric": "capex",
   "statement": "Total capex outgo for the overall fiscal is expected to be between INR1,100 crores and INR1,200 crores.",
   "quote": "And we feel that in the overall fiscal, it should be somewhere between INR1,100 crores, INR1,200 crores.",
   "page": 16,
   "horizon": "FY26",
   "quantitative": true
  },
  {
   "metric": "margin",
   "statement": "Mobile phone business margin is expected to remain between 2.8% and 3.2%.",
   "quote": "We still feel that we should be able to have a margin of somewhere between 2.8% to 3.1%, 3.2% in our mobile phone business.",
   "page": 9,
   "horizon": "next year / near term",
   "quantitative": true
  },
  {
   "metric": "volume",
   "statement": "Longcheer JV capacity for mobile phones is expected to be around 8 million to 10 million units in FY27.",
   "quote": "We feel that in '27 -- '26-'27, it will be around 8 million to 10 million units.",
   "page": 18,
   "horizon": "FY27",
   "quantitative": true
  }
 ],
 "delivered": [
  {
   "metric": "revenue",
   "statement": "Consolidated operating revenues for the quarter ended December 31, 2025 was INR10,678 crores.",
   "page": 3
  },
  {
   "metric": "profit",
   "statement": "Consolidated operating EBITDA for the quarter was INR421 crores and operating PAT was INR214 crores.",
   "page": 3
  },
  {
   "metric": "volume",
   "statement": "Smartphone volumes for Q3 were approximately 6.9 million units, bringing 9-month volumes closer to 27 million units.",
   "page": 7
  },
  {
   "metric": "revenue",
   "statement": "Consumer electronics revenue for the quarter was INR567 crores with an operating profit of INR24 crores.",
   "page": 5
  },
  {
   "metric": "revenue",
   "statement": "Home appliances revenue for the quarter was INR355 crores with an operating profit of INR41 crores.",
   "page": 5
  },
  {
   "metric": "balance sheet",
   "statement": "Working capital cycle remained at negative 7 days with a net debt position of INR246 crores.",
   "page": 4
  }
 ],
 "tone": "Cautious on near-term memory cost headwinds and post-festive demand, but confident on long-term scale and component integration.",
 "pushback": [
  {
   "topic": "Memory prices and demand",
   "gist": "Analysts questioned the impact of soaring global memory prices and supply constraints on smartphone demand and margins.",
   "page": 8
  },
  {
   "topic": "Vivo JV delay",
   "gist": "Multiple analysts pressed management on the reasons for the prolonged delay in receiving PN3 approval for the Vivo JV.",
   "page": 7
  },
  {
   "topic": "PLI extension uncertainty",
   "gist": "Analysts inquired about the potential margin impact if the mobile PLI scheme is not renewed.",
   "page": 8
  }
 ]
